  ],
  "negative_misalignment_reasons": [
    "Wall-decorating hooks do not serve the same purpose as the magnetic hooks I recently chose; I have no current decorating need.",
    "Tests, face masks, spray bottles, a temperature controller and tape do not address a task I currently need to complete, even if they could be useful generally."
  ],
